// Validar si el pago es válido
const invoice = $('Obtener Info Factura').first().json;
const input = $('Validar Entrada').first().json;
const conversion = input.conversion; 
const paymentAmount = Number(conversion ? input.converted_amount: input.payment_amount);
const totalPaid = Number(input.total_paid);
const remainingAmount = Number(invoice.total) - Number(invoice.paid_amount);

if (totalPaid <= 0) {
  return [{
    json: {
      error: true,
      message: "El monto del pago debe ser mayor a 0"
    }
  }];
}

// if (totalPaid > remainingAmount) {
//   return [{
//     json: {
//       error: true,
//       message: `El pago ($${totalPaid}) excede el monto pendiente ($${remainingAmount})`
//     }
//   }];
// }

if (invoice.payment_state === 'paid') {
  return [{
    json: {
      error: true,
      message: "Esta factura ya está completamente pagada"
    }
  }];
}

return [{
  json: {
    invoice: invoice,
    payment_amount: totalPaid,
    total_paid: Number(invoice.paid_amount) + Number(totalPaid), 
    remainingAmount: remainingAmount,
    remaining_after_payment: remainingAmount - totalPaid,
    will_be_fully_paid: (Number(remainingAmount) - Number(totalPaid)) <= 0.01
  }
}];

const query = $json.query;

const input = $input.first().json;
// Validar datos de entrada desde el trigger
const invoice_id = input.invoice_id || query?.invoice_id || '';
const cash_session_id = input.cash_session_id || query?.cash_session_id || null;
const payment_date = query?.payment_date || input.payment_date  || '';
const payment_amount = input.amount || query?.amount || query?.paid_amount || query?.payment_amount || 0;
const payment_method = query?.method || input.method  || '';
const payment_method_id = query?.payment_method_id || input.payment_method_id  || 1 ;
const user = input.user || query?.user || {};
const currency = input.payment_currency || query?.payment_currency || 'UYU';
const invoice_currency = input.invoice_currency || query?.invoice_currency || 'UYU';
const exchange_rate = input?.exchange_rate || query?.exchange_rate  || 1 ;
const converted_amount = input.converted_amount || query?.converted_amount || payment_amount;
const credit_payment = input.credit_payment
const prepaid = !invoice_id || invoice_id === '' ? true : false
const total_paid = query?.total_paid || payment_amount;
const notes = query?.notes || '';
const is_historical = query?.is_historical
const is_sales = query?.is_sales

// Validaciones básicas
// if (!invoice_id || invoice_id === '') {
//   return [{ json: { error: true, message: 'Numero de factura es requerido' } }];
// }

if (!payment_date || payment_date === '') {
  return [{ json: { error: true, message: 'La fecha del pago es requerida' } }];
}

if ((!total_paid || total_paid === '') && credit_payment?.length === 0) {
  return [{ json: { error: true, message: 'El monto del pago es requerido' } }];
}

if ((!payment_method || payment_method === '') && credit_payment?.length === 0) {
  return [{ json: { error: true, message: 'El método de pago es requerido' } }];
}

return [{
  json: {
    invoice_id,
    payment_date,
    payment_amount,
    payment_method,
    payment_method_id,
    cash_session_id,    
    user: user,
    currency,
    invoice_currency,
    exchange_rate,
    converted_amount,
    conversion: currency !== invoice_currency,
    credit_payment,
    prepaid,
    total_paid,
    notes,
    is_historical,
    is_sales
  }
}];

const paymentData = $('payment_values').item.json;
const isPrepaid = paymentData.prepaid;
const invoiceType = paymentData.invoice_type;

let invoiceDescription;
let orderDescription;

if (isPrepaid) {
    invoiceDescription = 'PREPAGO';
    orderDescription = '';
} else {
    const invoiceInfo = $('Obtener Info Factura').item.json;
    const orderDocNo = invoiceInfo?.order_doc_no || 'N/A';
    invoiceDescription = `Pago factura: ${invoiceInfo.doc_no}`;
    orderDescription = `Orden: ${orderDocNo}`;

    if (invoiceType === 'credit_note') {
      invoiceDescription = `Nota de crédito: ${invoiceInfo.doc_no}`;
      orderDescription = '';
    }
}

return {
    invoice_description: invoiceDescription,
    order_description: orderDescription
  };

const inputData = $('Validar Entrada').first().json;

// Datos base de la entrada
const is_sales = inputData.is_sales;
const exchangeRate = inputData.exchange_rate || 1;
const currency = inputData.currency;
let invoiceId = inputData.invoice_id;
let paidAmount = inputData.payment_amount;
let totalPaid = inputData.total_paid;

let outputs = [];

// 1. SI NO HAY INVOICE_ID, ES TRATADO COMO PRE-PAGO DIRECTO
if (!invoiceId) {
  // Según pto 2: La moneda de la factura es la del pago
  let invoiceCurrency = currency;
  // Según pto 4: Recalcular monto convertido
  let convertedAmount = paidAmount * exchangeRate;

  // Según pto 3: Lógica de signos (is_sales = false es compra/egreso, invertimos)
  if (is_sales === false) {
    paidAmount = -Math.abs(paidAmount);
    convertedAmount = -Math.abs(convertedAmount);
  }

  outputs.push({
    invoice_id: null,
    payment_amount: paidAmount,
    invoice_currency: invoiceCurrency,
    converted_amount: convertedAmount,
    prepaid: true,
    invoice_type: ''
  });

} else {
  // 2. CASO CON FACTURA (Se obtienen datos de nodos externos)
  const remainingAmount = $('Validar Pago').first().json.remainingAmount;
  const invoiceData = $('Obtener Info Factura').first().json;
  const invoiceCurrency = invoiceData.currency || 'UYU';
  const invoiceType = invoiceData.type;

  let convertedAmount = 0;

  // Cálculo de conversión estándar para el pago
  if (invoiceCurrency !== currency && invoiceCurrency !== 'UYU') {
    convertedAmount = paidAmount / exchangeRate;
  } else {
    convertedAmount = paidAmount * exchangeRate;
  }

  // A. SI HAY EXCEDENTE (Pago > Deuda) se genera un pago y un prepago
  if (totalPaid > remainingAmount) {
    let convertedAmountInfavor = totalPaid - remainingAmount;
    let amountInfavor = 0;

    // Ajustar el "monto a favor" según moneda
    if (invoiceCurrency !== currency && invoiceCurrency !== 'UYU') {
      amountInfavor = convertedAmountInfavor * exchangeRate;
    } else {
      amountInfavor = convertedAmountInfavor / exchangeRate;
    }

    // El pago real a la factura es el total menos el excedente
    paidAmount = paidAmount - amountInfavor;

    // Aplicar lógica de signos (Facturas de compra o Notas de crédito de venta)
    if ((invoiceType === 'invoice' && is_sales === false) || (invoiceType === 'credit_note' && is_sales === true)) {
      paidAmount = -Math.abs(paidAmount);
      amountInfavor = -Math.abs(amountInfavor);
      convertedAmount = -Math.abs(convertedAmount);
      convertedAmountInfavor = -Math.abs(convertedAmountInfavor);
    }

    // Salida 1: El pago aplicado a la factura
    outputs.push({
      invoice_id: invoiceId,
      payment_amount: paidAmount,
      invoice_currency: invoiceCurrency,
      converted_amount: convertedAmount - convertedAmountInfavor,
      prepaid: false,
      invoice_type: invoiceType
    });

    // Salida 2: El excedente como nuevo Prepago
    outputs.push({
      invoice_id: null,
      payment_amount: amountInfavor,
      invoice_currency: null,
      converted_amount: convertedAmountInfavor,
      prepaid: true,
      invoice_type: ''
    });

  } else {
    // B. PAGO NORMAL O MENOR A LA DEUDA
    if ((invoiceType === 'invoice' && is_sales === false) || (invoiceType === 'credit_note' && is_sales === true)) {
      paidAmount = -Math.abs(paidAmount);
      convertedAmount = -Math.abs(convertedAmount);
    }

    outputs.push({
      invoice_id: invoiceId,
      payment_amount: paidAmount,
      invoice_currency: invoiceCurrency,
      converted_amount: convertedAmount,
      prepaid: false,
      invoice_type: invoiceType
    });
  }
}

return {
  outputs: outputs
};
